type AppLanguageContextValue = {
  language: AppLanguage;
  setLanguage: (language: AppLanguage) => void;
  t: (englishText: string) => string;
};

const AppLanguageContext = createContext<AppLanguageContextValue>({
  language: "en",
  setLanguage: () => {},
  t: (text) => text,
});

function initialLanguage(): AppLanguage {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    return languages.includes(stored as AppLanguage) ? stored as AppLanguage : "en";
  } catch {
    return "en";
  }
}

export function AppLanguageProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<AppLanguage>(initialLanguage);
  const setLanguage = useCallback((next: AppLanguage) => {
    setLanguageState(next);
    try { localStorage.setItem(STORAGE_KEY, next); } catch { /* Server preference remains the source of truth. */ }
  }, []);
  const t = useCallback((englishText: string) => language === "en" ? englishText : messages[language][englishText] ?? englishText, [language]);
  useEffect(() => { document.documentElement.lang = language; }, [language]);
  const value = useMemo(() => ({ language, setLanguage, t }), [language, setLanguage, t]);
  return <AppLanguageContext.Provider value={value}>{children}</AppLanguageContext.Provider>;
}

export function useAppLanguage() {
  return useContext(AppLanguageContext);
}

export function isAppLanguage(value: string): value is AppLanguage {
  return languages.includes(value as AppLanguage);
}
